import type { SVGProps } from "react";

type FantasyGlyphProps = SVGProps<SVGSVGElement> & { path: string };

function FantasyGlyph({ path, ...props }: FantasyGlyphProps) {
  return (
    <svg {...props} viewBox="0 0 512 512" fill="currentColor">
      <path d={path} />
    </svg>
  );
}

